export const getGetChatConversationsConversationIdMessagesUrl = (conversationId: string,
    params?: GetChatConversationsConversationIdMessagesParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/chat/conversations/${conversationId}/messages?${stringifiedParams}` : `/chat/conversations/${conversationId}/messages`
}

